t = int(input())
for i in range(t):
	(n, m) = [int(x) for x in input().split()]
	if m < n:
		print('-1 -1')
		continue
	if n == 2:
		print('-1 -1')
	elif n == 3 or n == 4:
		if n == m:
			for i in range(1, n):
				print(i, ' ', i + 1)
			print(n, ' ', 1)
		else:
			print('-1 -1')
	else:
		diff = n - 4
		omen = diff + n
		if m > omen:
			print('-1 -1')
		else:
			temp = m - n
			temp = n - temp
			for i in range(1, temp):
				print(i, ' ', i + 1)
			print(temp, ' ', 1)
			if m - n:
				for i in range(temp + 1, n + 1):
					print(i, ' ', 1)
					print(i, ' ', 3)
